t.guides["forever/class/paladin/lumina-windsinger"] = (function() return {
		["At 18 {npc:246378}, inside {area:16602} on the bluffs north-west of the {area:156}, sends you south to the {area:228} in {zone:1421}."] = "На 18-м уровне {npc:246378} изнутри места {area:16602}, на утесах к северо-западу от места {area:156}, отправляет вас на юг: {area:228} ({zone:1421}).",
		["Back to the {area:228}"] = "Вернитесь в {area:228}",
		["Equip the {item:268484}. {quest:95140}, the great worgen, roams the woods south of the {area:228} toward the gates of {area:17065}. He is elite (level 25): the guide waits for level 25 first, and grouping up is encouraged; players have killed him from 22 up, one needed a second, another soloed him at 25. A purple shield guards him until your first swing with the blade lands: a message tells you it broke."] = "Наденьте {item:268484}. {quest:95140}, огромный ворген, бродит по лесам к югу от места {area:228} в сторону ворот ({area:17065}). Он элитный (25-й уровень): гайд сначала ждет 25-го уровня, и лучше собрать группу; игроки убивали его с 22-го уровня, одному понадобился напарник, другой справился в одиночку на 25-м. Пока ваш первый удар клинком не достигнет цели, его защищает фиолетовый щит: сообщение скажет, что щит разрушен.",
		["Free {npc:248755}"] = "Освободите {npc:248755}",
		["Goblin Woodcarvers, inside"] = "Гоблины-древорубы, внутри",
		["The Forsaken paladin's two-handed sword: rescue {quest:91862}, gather three parts, slay {quest:95140}."] = "Двуручный меч паладина Отрекшихся: спасите {quest:91862}, соберите три части, убейте {quest:95140}.",
		["The pyre on {area:172}"] = "Погребальный костер: {area:172}",
		["The {item:267361}"] = "{item:267361}",
		["The {item:272448}"] = "{item:272448}",
		["The {item:6995}"] = "{item:6995}",
		["from the {object:566037}"] = "Объект: {object:566037}",
		["{area:1581}, in the {area:20} mine"] = "{area:1581}, в шахте ({area:20})",
		["{item:267412}, from the Rot Hide gnolls"] = "{item:267412} – с гноллов из стаи Гнилошкуров",
		["{item:268484} and {item:267369} (Forsaken)"] = "{item:268484} и {item:267369} (Отрекшиеся)",
