t.guides["forever/class/rogue/blade-of-cunning-alliance"] = (function() return {
		["A dagger at 10 from your home town's rogue quests."] = "Кинжал на 10-м уровне за задания разбойников в вашем родном городе.",
		["At 10 {npc:1234}, the rogue trainer in the {area:2102} in {area:131}, sends you to {npc:5165} in {zone:1455}."] = "На 10-м уровне {npc:1234}, учитель разбойников ({area:2102}, {area:131}), отправляет вас к персонажу {npc:5165} ({zone:1455}).",
		["At 10 {npc:3599}, the rogue trainer in the {area:186} inn, gives you a rose for {npc:4163} in {zone:1457}. If you lose the rose, abandon the quest and take it again."] = "На 10-м уровне {npc:3599}, учитель разбойников в таверне ({area:186}), дает вам розу для персонажа {npc:4163} ({zone:1457}). Если потеряете розу, откажитесь от задания и возьмите его снова.",
		["At 10 {npc:917}, the rogue trainer upstairs in the Lion's Pride Inn in {area:87}, gives you a package for {npc:332} in {zone:1453}. Train {spell:921} if you lack it: this chain needs it."] = "На 10-м уровне {npc:917}, учитель разбойников наверху в таверне ({area:87}), дает вам сверток для персонажа {npc:332} ({zone:1453}). Изучите {spell:921}, если еще не знаете: эта цепочка требует этого навыка.",
		["Back to Mathias Shaw"] = "Назад к Матиасу Шоу",
		["Back to {npc:4163}"] = "Назад: {npc:4163}",
		["Back to {npc:5165}"] = "Назад к {npc:5165}",
		["Pick Pocket Sethir the Ancient for {item:7737}"] = "Обчистите карманы Сетира Древнего: {item:7737}",
		["{item:7298} (Alliance)"] = "{item:7298} (Альянс)",
		["{npc:332}, SI:7"] = "{npc:332}, ШРУ",
		["{spell:921} the {npc:6846} for the {item:7675}"] = "{spell:921}: {npc:6846} – {item:7675}",
} end)()
t.guides["forever/class/rogue/blade-of-cunning-horde"] = (function() return {
		["A dagger at 10 from your home town's rogue quests."] = "Кинжал на 10-м уровне за задания разбойников в вашем родном городе.",
		["At 10 {npc:2130}, the rogue trainer upstairs in the {area:2119} in {area:159}, sends you to {quest:1885} in the {zone:1458}."] = "На 10-м уровне {npc:2130}, учитель разбойников наверху ({area:2119}, {area:159}), отправит вас сюда: {quest:1885} ({zone:1458}).",
		["Back to {npc:6446}"] = "Назад: {npc:6446}",
		["Back to {npc:6467}"] = "Назад: {npc:6467}",
		["Pick Pocket Gamon for {item:7208}"] = "Обчистите карманы Гамона и добудьте {item:7208}",
		["The {object:36073}"] = "{object:36073}",
		["{item:7209}, once you have the key"] = "{item:7209}, когда добудете ключ",
		["{item:7295}, from the satchel"] = "{item:7295}, из сумки",
		["{item:7298} (Horde)"] = "{item:7298} (Орда)",
