} end)()
t.guides["forever/class/rogue/the-azure-key"] = (function() return {
		["At 50 {npc:3328} in the {object:172960} has it; so does {npc:4583} in the {zone:1458}'s {object:36073}."] = "На 50-м уровне его дает {npc:3328} ({object:172960}); а также {npc:4583} ({zone:1458}, {object:36073}).",
		["At 50 {npc:918} in {zone:1453}'s {object:2100} has it; so do Syurna in {zone:1457} and {npc:5165} in {zone:1455}."] = "На 50-м уровне его дает {npc:918} ({zone:1453}, {object:2100}); а также Сиарна ({zone:1457}) и {npc:5165} ({zone:1455}).",
		["Back to Xylem"] = "Назад к Ксилему",
		["Lord Ravenholdt"] = "Лорд Черный Ворон",
		["Morphaz in the {area:1417}"] = "Морфаз: {area:1417}",
		["Ravenholdt reputation"] = "Репутация у Черного Ворона",
		["Ravenholdt reputation and experience at 50; Classic's item choice may be gone on Forever."] = "Репутация у Черного Ворона и опыт на 50-м уровне; в Forever выбора предмета из Classic может не быть.",
		["{item:20022}: Morphaz, inside the temple"] = "{item:20022}: Морфаз, внутри храма",
		["{quest:8233} (Alliance)"] = "{quest:8233} (Альянс)",
		["{quest:8233} (Horde)"] = "{quest:8233} (Орда)",
} end)()
t.guides["forever/class/rogue/the-eye-of-bhossca"] = (function() return {
		["Back to the dead drop"] = "Вернитесь к тайнику",
		["C's dead drop"] = "Тайник C",
		["C's next job comes by letter: once you are level 30 and have done the horn job (The {item:210183}, its payment from this {object:410369} handed in), visit any capital city and C's letter arrives in the mailbox; only then does the {object:410369} near {area:204}, in southern Silverpine just south of {area:236}, offer it. The quest data lists a minimum of 25, but players get the letter, and the job, at 30."] = "Следующая работа от C приходит письмом: когда вы достигнете 30 уровня и выполните работу с рогом («{item:210183}», плата за нее получена в этом месте: {object:410369}), посетите любую столицу, и письмо от C придет в почтовый ящик; только после этого {object:410369} у места {area:204}, на юге Серебряного бора чуть южнее: {area:236}, предложит задание. В данных задания указан минимум 25, но игроки получают письмо и работу на 30 уровне.",
		["The {area:796}"] = "Локация: {area:796}",
		["The {item:277246}, C's payment for a solo job in the {area:796}, after The {item:210183}."] = "{item:277246} — плата от C за одиночную работу в месте {area:796}, после задания «{item:210183}».",
		["the locked reliquary in the Library"] = "запертая рака в библиотеке",
} end)()
t.guides["forever/class/rogue/the-horn-of-xelthos"] = (function() return {
