} end)()
t.guides["forever/class/warlock/felhunter-horde"] = (function() return {
		["At 30 {npc:5675}, in the {object:36082}, sends you to {npc:6251} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}. Take only one {quest:3001}: if {npc:6251} offers nothing, drop the duplicate from your log."] = "На 30-м уровне {npc:5675} ({object:36082}) отправляет вас к NPC {npc:6251} ({area:392}). Дирижабль летит из зоны {zone:1420} в {zone:1411}. Возьмите только одно задание {quest:3001}: если {npc:6251} ничего не предлагает, удалите дубликат из журнала.",
		["At 30 {npc:5875}, in the {object:172960} under the {object:172982}, sends you to {npc:6251} in {area:392}."] = "На 30-м уровне {npc:5875} ({object:172960}, под местом {object:172982}) отправляет вас к NPC {npc:6251} ({area:392}).",
		["Back to {npc:6293}"] = "Вернитесь: {npc:6293}",
		["Felhunter (Horde)"] = "Охотник Скверны (Орда)",
		["Rods of Channeling"] = "Жезлы направления",
		["The felhunter, the demon to bring against spellcasters, and a {item:22244} for your shards."] = "Охотник Скверны — демон против заклинателей, а также {item:22244} для ваших осколков.",
		["{item:6997}, in the {object:92423}"] = "{item:6997} — в предмете {object:92423}",
} end)()
t.guides["forever/class/warlock/imp-alliance"] = (function() return {
		["Imp (Alliance)"] = "Бес (Альянс)",
		["The {object:83763}"] = "{object:83763}",
		["Your first demon at level 1-4: the imp, from your start zone's warlock trainer."] = "Ваш первый демон на 1-4 уровне: бес, у учителя чернокнижников в стартовой зоне.",
